/// <summary>
/// <c>commit -m &lt;msg&gt;</c> (± <c>--allow-empty</c> ± <c>-- &lt;pathspecs&gt;</c>):
/// builds a tree from the index, consults <see cref="GitSim.PreCommitHook"/> (a
/// reject → non-zero exit with the message in output, exactly what
/// <c>GitCommitter</c> parses), then records the commit and advances HEAD.
/// Author/committer come from <c>GIT_AUTHOR_*</c>/<c>GIT_COMMITTER_*</c> when
/// present. When pathspecs follow <c>--</c>, the commit's tree restricts to only
/// those paths (overlaid on HEAD for non-pathspec paths); other staged paths stay
/// staged. The hook still sees ALL staged paths (matching real git).
/// </summary>
public static GitSimResult Commit(GitSimContext ctx)
{
    if (!ctx.TryRepo(out var wt))
        return GitSimResult.Fatal("not a git repository (or any of the parent directories): .git");

    var msg = ctx.ValueAfter("-m");
    if (msg is null)
        return ctx.Unsupported();

    var index = ctx.Index(wt);
    if (index.HasUnmerged)
        return GitSimResult.Code(1, "error: committing is not possible because you have unmerged files.\n");

    var store = wt.Repo.Objects;
    var headSha = wt.ResolveHead();
    var pathspecs = ctx.Pathspecs();

    // Build the tree: when pathspecs are given, start from HEAD and overlay
    // only the pathspec entries from the index.  Otherwise use the full index.
    var treeSha = pathspecs.Count > 0 && headSha is not null
        ? BuildPathspecTree(store, headSha, index, pathspecs)
        : TreeBuilder.BuildTreeFromIndex(store, index);

    if (ctx.PreCommitHook is not null)
    {
        // Real git fires the hook with ALL staged paths, not just the pathspec
        // subset — match that so hook tests are faithful.
        var staged = index.Stage0.Select(e => e.Path).ToList();
        var verdict = ctx.PreCommitHook(new GitSimCommitRequest(staged, msg, ctx.Environment));
        if (!verdict.Accepted)
            return GitSimResult.Code(1, verdict.Message.TrimEnd('\n') + "\n");
    }

    // "nothing to commit" for the pathspec case: compare each pathspec entry
    // in the index against HEAD. If none differ, there is nothing new to land.
    if (!ctx.Has("--allow-empty"))
    {
        if (pathspecs.Count > 0 && headSha is not null)
        {
            if (!HasPathspecChanges(store, index, headSha, pathspecs))
                return GitSimResult.Code(1, "nothing to commit, working tree clean\n");
        }
        else if (headSha is not null
                 && store.TryGetCommit(headSha, out var head)
                 && string.Equals(head.TreeSha, treeSha, StringComparison.Ordinal))
        {
            return GitSimResult.Code(1, "nothing to commit, working tree clean\n");
        }
    }

    var when = wt.Repo.NextTimestamp();
    var author = PersonFromEnv(ctx, wt, "GIT_AUTHOR", when);
    var committer = PersonFromEnv(ctx, wt, "GIT_COMMITTER", when);
    var parents = headSha is null ? Array.Empty<string>() : [headSha];
    var commitSha = store.PutCommit(new GitCommit(treeSha, parents, author, committer, msg));
    wt.MoveHeadTo(commitSha);

    var branch = wt.Head.SymbolicRef?["refs/heads/".Length..] ?? "detached";
    return GitSimResult.Ok($"[{branch} {commitSha[..7]}] {Subject(msg)}\n");
}

/// <summary>
/// Builds a tree that starts from <paramref name="headSha"/> and overlays
/// only the index entries matching <paramref name="pathspecs"/>. All other
/// paths stay at their HEAD version regardless of the index.
/// </summary>
private static string BuildPathspecTree(
    GitObjectStore store, string headSha, GitIndex index, IReadOnlyList<string> pathspecs)
{
    // Start from HEAD's flattened tree.
    var headEntries = TreeBuilder.FlattenTree(store, TreeBuilder.ResolveTreeSha(store, headSha) ?? headSha);

    // Overlay only the pathspec entries from the index.
    foreach (var (path, entry) in index.Stage0)
    {
        if (MatchesAny(path, pathspecs))
            headEntries[path] = entry;
    }

    return TreeBuilder.BuildTree(store,
        headEntries.Select(kv => (kv.Key, kv.Value)).ToList());
}

/// <summary>
/// Returns true when at least one pathspec entry in the index differs from HEAD.
/// </summary>
private static bool HasPathspecChanges(
    GitObjectStore store, GitIndex index, string headSha, IReadOnlyList<string> pathspecs)
{
    var headEntries = TreeBuilder.FlattenTree(store, TreeBuilder.ResolveTreeSha(store, headSha) ?? headSha);

    foreach (var (path, entry) in index.Stage0)
    {
        if (!MatchesAny(path, pathspecs))
            continue;
        if (!headEntries.TryGetValue(path, out var headEntry)
            || !string.Equals(headEntry.Sha, entry.Sha, StringComparison.Ordinal))
            return true;
    }

    return false;
}

