using VisualRelay.Core.Execution;

namespace VisualRelay.Core.Init;

/// <summary>
/// Creates a setup commit of <c>.relay/config.json</c> and
/// <c>.relay/.gitignore</c> at the end of initialization. Called from both
/// the CLI bootstrap path (<see cref="ProjectBootstrapper.BootstrapAsync"/>)
/// and the GUI create-config path.
/// </summary>
public static class SetupCommitHelper
{
    private const string SetupCommitMessage = "chore(relay): initialize project config";

    // Paths relative to the repo root.
    private static readonly string[] SetupPaths = [".relay/config.json", ".relay/.gitignore"];

    /// <summary>
    /// Stages <c>.relay/config.json</c> and <c>.relay/.gitignore</c> by explicit
    /// pathspec and commits them with <see cref="SetupCommitMessage"/>.
    /// Idempotent: a no-op when both files are already tracked and unchanged.
    /// User-staged changes for other paths are never swept into this commit.
    /// </summary>
    /// <returns>
    /// <c>null</c> on success (including the no-op case), or a
    /// <see cref="SetupCheckDiagnostic"/> when the commit is rejected by the
    /// repo's own pre-commit hook.
    /// </returns>
    public static async Task<SetupCheckDiagnostic?> TryCommitSetupFilesAsync(
        string rootPath,
        IGitInvoker? gitInvoker = null,
        CancellationToken cancellationToken = default)
    {
        var gi = gitInvoker ?? new GitInvoker();
        const int timeoutMs = 30_000;

        // 1. Skip early if the files don't exist on disk.
        var anyFileExists = false;
        foreach (var p in SetupPaths)
        {
            if (File.Exists(Path.Combine(rootPath, p)))
            {
                anyFileExists = true;
                break;
            }
        }
        if (!anyFileExists)
            return null;

        // 2. git add -- .relay/config.json .relay/.gitignore
        //    Only stages our two files; never touches other staged entries.
        var addArgs = new List<string> { "add", "--" };
        addArgs.AddRange(SetupPaths);

        var addResult = await gi.RunAsync(rootPath, addArgs, cancellationToken,
            TimeSpan.FromMilliseconds(timeoutMs));

        if (addResult.ExitCode != 0)
            return WriteDiagnostic(rootPath, "git add", addResult, timeoutMs);

        // 3. Idempotency: git diff --cached --quiet -- <paths>
        //    Exit 0 means nothing new is staged for these paths vs HEAD.
        var diffArgs = new List<string> { "diff", "--cached", "--quiet", "--" };
        diffArgs.AddRange(SetupPaths);

        var diffResult = await gi.RunAsync(rootPath, diffArgs, cancellationToken,
            TimeSpan.FromMilliseconds(timeoutMs));

        if (diffResult.ExitCode == 0)
            return null; // Nothing new — idempotent no-op.

        // 4. git commit -m "chore(relay): initialize project config" -- <paths>
        //    Explicit pathspec so user-staged files are never swept in.
        var commitArgs = new List<string> { "commit", "-m", SetupCommitMessage, "--" };
        commitArgs.AddRange(SetupPaths);

        var commitResult = await gi.RunAsync(rootPath, commitArgs, cancellationToken,
            TimeSpan.FromMilliseconds(timeoutMs));

        if (commitResult.ExitCode == 0)
            return null; // Success.

        // 5. Hook rejection (or other failure) — surface through setup-check plumbing.
        return WriteDiagnostic(rootPath, "git commit", commitResult, timeoutMs);
    }

    private static SetupCheckDiagnostic WriteDiagnostic(
        string rootPath, string command, (int ExitCode, string Output, bool TimedOut) result,
        int timeoutMs)
    {
        const string cwd = "."; // rootPath-relative
        var diagnostic = new SetupCheckDiagnostic(
            Status: "rejected",
            Message: "Setup commit rejected by pre-commit hook",
            Path: cwd,
            Command: command,
            ExitCode: result.ExitCode,
            OutputTail: result.Output.TrimEnd(),
            TimedOut: result.TimedOut);

        diagnostic.WriteArtifact(
            rootPath: rootPath,
            command: command,
            cwd: cwd,
            timeoutMs: timeoutMs,
            exitCode: result.ExitCode,
            timedOut: result.TimedOut,
            output: result.Output);

        return diagnostic;
    }
}

