            return null; // Success.

        // 5. Hook rejection (or other failure) — surface through setup-check plumbing.
        return BuildDiagnostic(rootPath, "git commit", commitResult, timeoutMs);
    }

    private static SetupCheckDiagnostic BuildDiagnostic(
        string rootPath, string command,
        (int ExitCode, string Output, bool TimedOut) result, int timeoutMs)
    {
        var artifactPath = SetupCheckDiagnostic.WriteArtifact(
            rootPath: rootPath,
            command: command,
            cwd: ".",
            timeoutMs: timeoutMs,
            exitCode: result.ExitCode,
            timedOut: result.TimedOut,
            output: result.Output);

        return new SetupCheckDiagnostic(
            Command: command,
            Cwd: ".",
            TimeoutMs: timeoutMs,
            ExitCode: result.ExitCode,
            TimedOut: result.TimedOut,
            OutputTail: SetupCheckDiagnostic.CapForState(result.Output),
            ArtifactPath: artifactPath,
            CapturedUtc: DateTimeOffset.UtcNow);
